/**
 * Add your custom code to this function.
 * @param {RelayApp.Input} input An object containing the values of the inputs configured for this step.
 * @returns {RelayApp.Output} Object containing configured output values.
 */
export default function runCode(input) {
  const body = input["emailBody"] || "";
  const truncated =
    body.length > 2700 ? body.substring(0, 2700) + "... [truncated]" : body;
  return { truncatedBody: truncated };
}
